import React, { useContext, useEffect } from "react";
import noteContext from "../context/notes/noteContext";

const UndoRedoButtons = () => {
  const context = useContext(noteContext);
  const { undo, redo, undoStack, redoStack } = context;

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (event) => {
      // Ctrl+Z for undo
      if (event.ctrlKey && event.key === 'z' && !event.shiftKey) {
        event.preventDefault();
        if (undoStack.length > 0) {
          undo();
        }
      }
      // Ctrl+Shift+Z or Ctrl+Y for redo
      else if ((event.ctrlKey && event.shiftKey && event.key === 'Z') || 
               (event.ctrlKey && event.key === 'y')) {
        event.preventDefault();
        if (redoStack.length > 0) {
          redo();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [undo, redo, undoStack.length, redoStack.length]);

  const getLastActionDescription = (stack) => {
    if (stack.length === 0) return '';
    
    const lastAction = stack[stack.length - 1];
    switch (lastAction.action) {
      case 'ADD':
        return `Add "${lastAction.data.title}"`;
      case 'DELETE':
        return `Delete "${lastAction.data.title}"`;
      case 'UPDATE':
        return `Update "${lastAction.data.oldNote?.title || 'note'}"`;
      default:
        return lastAction.action;
    }
  };

  return (
    <div className="btn-group" role="group" aria-label="Undo Redo Controls">
      <button
        type="button"
        className="btn btn-outline-secondary btn-sm"
        onClick={undo}
        disabled={undoStack.length === 0}
        title={`Undo: ${getLastActionDescription(undoStack)} (Ctrl+Z)`}
      >
        <i className="fas fa-undo me-1"></i>
        Undo
        {undoStack.length > 0 && (
          <span className="badge bg-secondary ms-1">{undoStack.length}</span>
        )}
      </button>
      
      <button
        type="button"
        className="btn btn-outline-secondary btn-sm"
        onClick={redo}
        disabled={redoStack.length === 0}
        title={`Redo: ${getLastActionDescription(redoStack)} (Ctrl+Shift+Z)`}
      >
        <i className="fas fa-redo me-1"></i>
        Redo
        {redoStack.length > 0 && (
          <span className="badge bg-secondary ms-1">{redoStack.length}</span>
        )}
      </button>

      {(undoStack.length > 0 || redoStack.length > 0) && (
        <div className="btn-group-text small text-muted d-none d-md-block">
          Use Ctrl+Z / Ctrl+Shift+Z
        </div>
      )}
    </div>
  );
};

export default UndoRedoButtons;
